// A copy of the `ts` bundler this package ships under the specifier the toolchain allows. The bundler is
// imported through the loader of the toolchain, so this file must never run; when it runs, it leaves a marker.
import { writeFileSync } from 'node:fs';

const { BEYOND_CONFINEMENT_MARKER: marker } = process.env;
marker && writeFileSync(`${marker}.shadow-bundler`, 'executed');

export class Module {}
